// BlackWhiteFrontDoor.swift: the first thing "Black & White.app" runs.
//
// This port ships with no game content at all. The first time it is opened it asks for the
// player's own copy of Black & White (a disc image, a folder that is a copy of the disc, or
// the folder the game is installed in, of any version), checks it file by file against
// game-manifest.json, builds the game folder from it — the program files are generated by
// the app itself, so no copy of the game is refused for carrying a different program — and
// from then on starts the game at once. What the player chose is only read, never changed.
//
//   swiftc -O -parse-as-library -target arm64-apple-macos13.0 BlackWhiteFrontDoor.swift
//
// build-app.py does that and puts the result in the app as Contents/MacOS/BlackWhite. The
// shell launcher it hands over to is Resources/BlackWhiteLauncher.sh (launcher.sh).
//
// Without a window, for tests:
//   --selftest            checks the parsing, hashing and setup detection, one line each
//   --check-setup         prints where the game folder, disc copy and program are, and
//                         whether set-up is complete (exit 0) or not (exit 1)
//   --import-iso <path>   sets the game up from a disc image, printing each step
//   --import-disc <path>  the same from a folder that is a copy of the disc
//
// BW_APP_SUPPORT_DIR and BW_APP_LOGS_DIR move the player's folders, as they do for
// launcher.sh; BW_UNSHIELD names an unshield other than the one bundled in the app.

import AppKit
import CryptoKit
import Foundation
import SwiftUI
import UniformTypeIdentifiers

let fallbackPin = "86a30b08ab2ea8a240403d37f8f0303cf65aa5cde8e7f673049ab01654ccf755"

// MARK: - Where things are

func envValue(_ key: String) -> String? {
    guard let raw = getenv(key) else { return nil }
    let value = String(cString: raw)
    return value.isEmpty ? nil : value
}

enum Paths {
    static var contents: URL {
        if let root = envValue("BW_APP_BUNDLE_ROOT") { return URL(fileURLWithPath: root, isDirectory: true) }
        return Bundle.main.bundleURL.appendingPathComponent("Contents", isDirectory: true)
    }

    static var resources: URL { contents.appendingPathComponent("Resources", isDirectory: true) }

    /// The launcher script the front door hands over to. It lives in Resources (the bundle
    /// seal covers it there; a loose script in MacOS cannot be signed), with the MacOS
    /// place kept for bundles built before it moved.
    static var launcher: URL {
        let candidates = [
            contents.appendingPathComponent("Resources/BlackWhiteLauncher.sh"),
            contents.appendingPathComponent("MacOS/BlackWhiteLauncher"),
        ]
        return candidates.first { FileManager.default.fileExists(atPath: $0.path) } ?? candidates[0]
    }

    static var manifest: URL? {
        let candidates = [
            resources.appendingPathComponent("game-manifest.json"),
            Bundle.main.bundleURL.appendingPathComponent("Contents/Resources/game-manifest.json"),
            URL(fileURLWithPath: CommandLine.arguments[0]).deletingLastPathComponent()
                .appendingPathComponent("../Resources/game-manifest.json"),
        ]
        return candidates.first { FileManager.default.fileExists(atPath: $0.path) }
    }

    /// The program files the app generates the game program from at set-up, bundled flat:
    /// runblack.exe, the three libraries and the script library.
    static var programKit: URL? {
        let dir = resources.appendingPathComponent("ProgramKit", isDirectory: true)
        return FileManager.default.fileExists(atPath: dir.path) ? dir : nil
    }

    static var unshield: URL? {
        var candidates: [URL] = [contents.appendingPathComponent("Helpers/unshield")]
        if let named = envValue("BW_UNSHIELD") { candidates.insert(URL(fileURLWithPath: named), at: 0) }
        candidates += [URL(fileURLWithPath: "/opt/homebrew/bin/unshield"),
                       URL(fileURLWithPath: "/usr/local/bin/unshield")]
        return candidates.first { FileManager.default.isExecutableFile(atPath: $0.path) }
    }

    static var support: URL {
        if let dir = envValue("BW_APP_SUPPORT_DIR") { return URL(fileURLWithPath: dir, isDirectory: true) }
        return FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/Black & White", isDirectory: true)
    }
}

// MARK: - Small pieces

func readConf(_ url: URL) -> [String: String] {
    guard let text = try? String(contentsOf: url, encoding: .utf8) else { return [:] }
    var values: [String: String] = [:]
    for rawLine in text.split(omittingEmptySubsequences: false, whereSeparator: { $0.isNewline }) {
        let line = String(rawLine).trimmingCharacters(in: .whitespaces)
        if line.isEmpty || line.hasPrefix("#") { continue }
        guard let eq = line.firstIndex(of: "=") else { continue }
        let key = line[..<eq].trimmingCharacters(in: .whitespaces)
        var value = line[line.index(after: eq)...].trimmingCharacters(in: .whitespaces)
        if value.count >= 2, value.hasPrefix("\""), value.hasSuffix("\"") {
            value = String(value.dropFirst().dropLast())
        }
        values[key] = value
    }
    return values
}

func sha256File(_ url: URL) throws -> String {
    let handle = try FileHandle(forReadingFrom: url)
    defer { try? handle.close() }
    var hash = SHA256()
    while true {
        let block = try handle.read(upToCount: 1 << 20) ?? Data()
        if block.isEmpty { break }
        hash.update(data: block)
    }
    return hash.finalize().map { String(format: "%02x", $0) }.joined()
}

private let crcTable: [UInt32] = (0..<256).map { start in
    var c = UInt32(start)
    for _ in 0..<8 { c = (c & 1) != 0 ? 0xEDB8_8320 ^ (c >> 1) : c >> 1 }
    return c
}

func crc32(_ data: Data) -> UInt32 {
    var c: UInt32 = 0xFFFF_FFFF
    for byte in data { c = crcTable[Int((c ^ UInt32(byte)) & 0xFF)] ^ (c >> 8) }
    return c ^ 0xFFFF_FFFF
}

func removeTree(_ url: URL) {
    let fm = FileManager.default
    guard fm.fileExists(atPath: url.path) else { return }
    let chmod = Process()
    chmod.executableURL = URL(fileURLWithPath: "/bin/chmod")
    chmod.arguments = ["-R", "u+w", url.path]
    try? chmod.run()
    chmod.waitUntilExit()
    try? fm.removeItem(at: url)
}

// MARK: - Is the game set up?

struct Setup {
    var gameDir: URL
    var discDir: URL
    var exe: URL?
    var pin: String
    var problems: [String]
    var complete: Bool { problems.isEmpty }
}

func evaluate(gameDir: URL, discDir: URL, exeNamed: String?, pin: String) -> Setup {
    let fm = FileManager.default
    var problems: [String] = []
    if !fm.fileExists(atPath: gameDir.path) {
        problems.append("no game folder at \(gameDir.path)")
    } else {
        for needed in ["lhlogr.dll", "LHaudiodllR.dll", "LHMultiplayerR.dll", "Plug Ins/ScriptLibraryR.dll"]
        where !fm.fileExists(atPath: gameDir.appendingPathComponent(needed).path) {
            problems.append("the game folder has no \(needed)")
        }
    }
    if !fm.fileExists(atPath: discDir.path) {
        problems.append("no disc copy at \(discDir.path)")
    }
    if !fm.fileExists(atPath: discDir.path + ".volume") {
        problems.append("no volume file beside the disc copy")
    }
    var exe: URL?
    let candidates = exeNamed.map { [URL(fileURLWithPath: $0)] } ?? [
        gameDir.appendingPathComponent("runblack-decrypted.exe"),
        gameDir.appendingPathComponent("runblack.exe"),
        discDir.appendingPathComponent("crack/runblack.exe"),
    ]
    for candidate in candidates where fm.fileExists(atPath: candidate.path) {
        if (try? sha256File(candidate)) == pin { exe = candidate; break }
    }
    if exe == nil { problems.append("no program matching this build on the disc or in the game folder") }
    return Setup(gameDir: gameDir, discDir: discDir, exe: exe, pin: pin, problems: problems)
}

func currentSetup(pinOverride: String? = nil) -> Setup {
    var conf = readConf(Paths.resources.appendingPathComponent("defaults.conf"))
    for (key, value) in readConf(Paths.support.appendingPathComponent("settings.conf")) { conf[key] = value }
    let gameDir = conf["GAME_DIR"].map { URL(fileURLWithPath: $0) }
        ?? Paths.support.appendingPathComponent("Game", isDirectory: true)
    let discDir = conf["DISC_DIR"].map { URL(fileURLWithPath: $0) }
        ?? Paths.support.appendingPathComponent("Disc", isDirectory: true)
    return evaluate(gameDir: gameDir, discDir: discDir, exeNamed: conf["EXE"],
                    pin: pinOverride ?? conf["EXE_SHA256"] ?? fallbackPin)
}

// MARK: - The import

struct ImportFailure: Error {
    var message: String
}

struct ManifestEntry {
    var dest: String
    var size: Int
    var sha256: String
    var variants: [(size: Int, sha256: String)]
    var checkAny: Bool
    var optional: Bool
    var mutable: Bool
    var from: String
    var src: String

    /// Whether a file made from the player's copy may stand in the game folder: a known
    /// form of the file, any content at all for the files that carry a language, or the
    /// right size for the two files the game itself rewrites.
    func accepts(size madeSize: Int, sha256 madeSha: String) -> Bool {
        if checkAny { return true }
        if mutable { return madeSize == size }
        if madeSize == size && madeSha == sha256 { return true }
        return variants.contains { $0.size == madeSize && $0.sha256 == madeSha }
    }
}

struct ProgramFile {
    var dest: String
    var size: Int
    var sha256: String
}

func loadManifest() throws -> (files: [ManifestEntry], program: [ProgramFile]) {
    guard let url = Paths.manifest else {
        throw ImportFailure(message: "game-manifest.json is missing from the app, so your copy of the game cannot be checked. This copy of the app is incomplete.")
    }
    let data = try Data(contentsOf: url)
    guard let root = try JSONSerialization.jsonObject(with: data) as? [String: Any],
          root["format"] as? Int == 2,
          let files = root["files"] as? [[String: Any]],
          let program = root["program"] as? [[String: Any]] else {
        throw ImportFailure(message: "\(url.lastPathComponent) is not a manifest this app understands.")
    }
    let entries = files.compactMap { entry -> ManifestEntry? in
        guard let dest = entry["dest"] as? String, let size = entry["size"] as? Int,
              let sha = entry["sha256"] as? String, let from = entry["from"] as? String,
              let src = entry["src"] as? String else { return nil }
        let variants = (entry["variants"] as? [[String: Any]] ?? []).compactMap { v -> (size: Int, sha256: String)? in
            guard let s = v["size"] as? Int, let h = v["sha256"] as? String else { return nil }
            return (s, h)
        }
        return ManifestEntry(dest: dest, size: size, sha256: sha, variants: variants,
                             checkAny: entry["check"] as? String == "any",
                             optional: entry["optional"] as? Bool ?? false,
                             mutable: entry["mutable"] as? Bool ?? false,
                             from: from, src: src)
    }
    let programFiles = program.compactMap { entry -> ProgramFile? in
        guard let dest = entry["dest"] as? String, let size = entry["size"] as? Int,
              let sha = entry["sha256"] as? String else { return nil }
        return ProgramFile(dest: dest, size: size, sha256: sha)
    }
    return (entries, programFiles)
}

struct VolumeDescriptor {
    var label: String
    var sectors: UInt32
    var serial: UInt32
}

func readVolumeDescriptor(_ iso: URL) throws -> VolumeDescriptor {
    let handle = try FileHandle(forReadingFrom: iso)
    defer { try? handle.close() }
    try handle.seek(toOffset: 16 * 2048)
    guard let sector = try handle.read(upToCount: 2048), sector.count == 2048,
          sector[0] == 1, String(decoding: sector[1..<6], as: UTF8.self) == "CD001" else {
        throw ImportFailure(message: "That file is not a disc image. Choose the .iso image of your Black & White disc.")
    }
    let bytes = [UInt8](sector)
    let label = String(decoding: bytes[40..<72], as: UTF8.self)
        .trimmingCharacters(in: CharacterSet(charactersIn: " \0"))
    let sectors = UInt32(bytes[80]) | UInt32(bytes[81]) << 8 | UInt32(bytes[82]) << 16 | UInt32(bytes[83]) << 24
    return VolumeDescriptor(label: label, sectors: sectors, serial: crc32(sector))
}

/// A file at a path that may differ only in the case of its letters (discs and cabinets
/// do not agree with every file system about case).
func locate(_ base: URL, _ relative: String) -> URL? {
    let fm = FileManager.default
    let direct = relative.split(separator: "/").reduce(base) { $0.appendingPathComponent(String($1)) }
    if fm.fileExists(atPath: direct.path) { return direct }
    var here = base
    for part in relative.split(separator: "/") {
        guard let entries = try? fm.contentsOfDirectory(atPath: here.path),
              let match = entries.first(where: { $0.lowercased() == part.lowercased() }) else { return nil }
        here = here.appendingPathComponent(match)
    }
    return here
}

func copyHashed(_ src: URL, _ dst: URL) throws -> (size: Int, sha256: String) {
    let fm = FileManager.default
    try fm.createDirectory(at: dst.deletingLastPathComponent(), withIntermediateDirectories: true)
    fm.createFile(atPath: dst.path, contents: nil)
    let input = try FileHandle(forReadingFrom: src)
    let output = try FileHandle(forWritingTo: dst)
    defer { try? input.close(); try? output.close() }
    var hash = SHA256()
    var size = 0
    while true {
        let block = try input.read(upToCount: 1 << 20) ?? Data()
        if block.isEmpty { break }
        hash.update(data: block)
        try output.write(contentsOf: block)
        size += block.count
    }
    return (size, hash.finalize().map { String(format: "%02x", $0) }.joined())
}

/// Finding a file inside an installed copy of the game: at its own path, at the place a
/// real installation actually puts it (the installer keeps some meshes under Data/ where
/// the game folder keeps them under Data/Misc/), or anywhere by name.
struct FolderIndex {
    var byPath: [String: URL] = [:]
    var byName: [String: [URL]] = [:]

    init(root: URL) {
        let fm = FileManager.default
        guard let walker = fm.enumerator(at: root, includingPropertiesForKeys: nil) else { return }
        for case let url as URL in walker {
            var isDir: ObjCBool = false
            fm.fileExists(atPath: url.path, isDirectory: &isDir)
            if isDir.boolValue { continue }
            let rel = String(url.path.dropFirst(root.path.count + 1))
            byPath[rel.lowercased()] = url
            byName[url.lastPathComponent.lowercased(), default: []].append(url)
        }
    }

    func find(_ entry: ManifestEntry) -> URL? {
        if let hit = byPath[entry.dest.lowercased()] { return hit }
        if entry.dest.hasPrefix("Data/Misc/"),
           let hit = byPath[("Data/" + entry.dest.dropFirst("Data/Misc/".count)).lowercased()] { return hit }
        let name = entry.dest.split(separator: "/").last.map(String.init) ?? ""
        let candidates = byName[name.lowercased()] ?? []
        if candidates.count == 1 { return candidates[0] }
        for candidate in candidates {
            let size = (try? candidate.resourceValues(forKeys: [.fileSizeKey]))?.fileSize ?? -1
            if let hash = try? sha256File(candidate), entry.accepts(size: size, sha256: hash) { return candidate }
        }
        return candidates.first
    }
}

final class Importer {
    var progress: (String, Double?) -> Void = { _, _ in }
    private let fm = FileManager.default

    func importISO(_ iso: URL, into dest: URL) throws {
        let descriptor = try readVolumeDescriptor(iso)
        progress("Checking the disc image…", nil)
        let imageHash = try sha256File(iso)
        try run(dest: dest, label: descriptor.label, sectors: descriptor.sectors,
                serial: descriptor.serial, imageHash: imageHash,
                imageSize: (try fm.attributesOfItem(atPath: iso.path)[.size] as? NSNumber)?.int64Value ?? 0) { stage in
            progress("Copying the disc…", nil)
            try self.runLogged("/usr/bin/bsdtar",
                               ["-xf", iso.path, "-C", stage.path, "--no-same-owner", "--no-same-permissions"],
                               logName: "disc-copy.log", in: stage.deletingLastPathComponent())
        }
    }

    func importDiscFolder(_ folder: URL, into dest: URL) throws {
        guard let cab = try? fm.contentsOfDirectory(atPath: folder.path),
              cab.contains(where: { $0.lowercased() == "data1.cab" }) else {
            throw ImportFailure(message: "That folder is not a copy of the Black & White disc: it has no data1.cab at the top. Choose the disc image, or the folder that holds the disc's own files.")
        }
        try run(dest: dest, label: "BNW", sectors: 0, serial: crc32(Data("BNW".utf8)),
                imageHash: "", imageSize: 0) { stage in
            progress("Copying the disc…", nil)
            for name in try self.fm.contentsOfDirectory(atPath: folder.path) {
                try self.fm.copyItem(at: folder.appendingPathComponent(name),
                                     to: stage.appendingPathComponent(name))
            }
        }
    }

    /// An installed copy of the game (any version, any language) as the source: its files
    /// are already in the game folder's layout, so they are taken as they are, and an empty
    /// disc copy with the right label answers the game's disc check.
    func importGameFolder(_ folder: URL, into dest: URL) throws {
        var isDir: ObjCBool = false
        guard fm.fileExists(atPath: folder.appendingPathComponent("Data").path, isDirectory: &isDir), isDir.boolValue,
              fm.fileExists(atPath: folder.appendingPathComponent("Scripts").path, isDirectory: &isDir), isDir.boolValue else {
            throw ImportFailure(message: "That folder is not an installed copy of Black & White: it has no Data and Scripts folders. Choose the disc image, a folder that is a copy of the disc, or the folder the game is installed in.")
        }
        try run(dest: dest, label: "BNW", sectors: 0, serial: crc32(Data(folder.path.utf8)),
                imageHash: "", imageSize: 0, installedFolder: folder) { _ in }
    }

    private func runLogged(_ tool: String, _ arguments: [String], logName: String, in folder: URL) throws {
        let logURL = folder.appendingPathComponent(logName)
        fm.createFile(atPath: logURL.path, contents: nil)
        let log = try FileHandle(forWritingTo: logURL)
        let process = Process()
        process.executableURL = URL(fileURLWithPath: tool)
        process.arguments = arguments
        process.standardOutput = log
        process.standardError = log
        try process.run()
        process.waitUntilExit()
        try? log.close()
        if process.terminationStatus != 0 {
            let tail = (try? String(contentsOf: logURL, encoding: .utf8)) ?? ""
            throw ImportFailure(message: "\(URL(fileURLWithPath: tool).lastPathComponent) could not read the disc (exit \(process.terminationStatus)). Its last lines:\n\(tail.split(separator: "\n").suffix(5).joined(separator: "\n"))")
        }
    }

    private func run(dest: URL, label: String, sectors: UInt32, serial: UInt32,
                     imageHash: String, imageSize: Int64, installedFolder: URL? = nil,
                     prepareDisc: (URL) throws -> Void) throws {
        try fm.createDirectory(at: dest, withIntermediateDirectories: true)
        let free = (try fm.attributesOfFileSystem(forPath: dest.path)[.systemFreeSize] as? NSNumber)?.int64Value ?? 0
        if free < 7_000_000_000 {
            throw ImportFailure(message: "Not enough disk space: setting up needs about 3 GB and should leave room to spare, but only \(free / 1_000_000_000) GB is free.")
        }
        let work = dest.appendingPathComponent(".import-\(UUID().uuidString)", isDirectory: true)
        try fm.createDirectory(at: work, withIntermediateDirectories: true)
        defer { removeTree(work) }
        let discStage = work.appendingPathComponent("Disc", isDirectory: true)
        try fm.createDirectory(at: discStage, withIntermediateDirectories: true)
        try prepareDisc(discStage)

        var cabDir: URL?
        if installedFolder == nil {
            guard let cabFile = try fm.contentsOfDirectory(atPath: discStage.path)
                .first(where: { $0.lowercased() == "data1.cab" }) else {
                throw ImportFailure(message: "This disc has no data1.cab, so it is not a Black & White PC disc.")
            }
            guard let unshield = Paths.unshield else {
                throw ImportFailure(message: "unshield is missing, so the disc's installer files cannot be unpacked. This copy of the app is incomplete.")
            }
            progress("Unpacking the game's installer files…", nil)
            let dir = work.appendingPathComponent("cab", isDirectory: true)
            try runLogged(unshield.path, ["-d", dir.path, "x", discStage.appendingPathComponent(cabFile).path],
                          logName: "unshield.log", in: work)
            cabDir = dir
        }
        let folderIndex = installedFolder.map { FolderIndex(root: $0) }

        let (manifest, program) = try loadManifest()
        progress("Building the game folder (\(manifest.count) files)…", 0)
        let gameStage = work.appendingPathComponent("Game", isDirectory: true)
        var missing: [String] = []
        var different: [String] = []
        var total: Int64 = 0
        for (index, entry) in manifest.enumerated() {
            let src: URL?
            if let folderIndex {
                src = folderIndex.find(entry)
            } else {
                src = locate(entry.from == "cab" ? cabDir! : discStage, entry.src)
            }
            guard let src else {
                if !entry.optional { missing.append(entry.dest) }
                continue
            }
            let dst = entry.dest.split(separator: "/").reduce(gameStage) { $0.appendingPathComponent(String($1)) }
            let made = try copyHashed(src, dst)
            total += Int64(made.size)
            if !entry.accepts(size: made.size, sha256: made.sha256) { different.append(entry.dest) }
            if index % 25 == 0 { progress("Building the game folder (\(index + 1) of \(manifest.count))…", Double(index) / Double(manifest.count)) }
        }
        if !missing.isEmpty || !different.isEmpty {
            let first = (missing + different).prefix(8).joined(separator: ", ")
            throw ImportFailure(message: "That doesn't look like a complete copy of Black & White.\n\n\(missing.count) files were not found and \(different.count) were not the game's files (first: \(first)).\n\nNothing was set up, and nothing you chose was changed. Any complete copy of the game works: the original disc, a patched copy, or another language edition.")
        }

        // The program itself is generated here, from the program files bundled with the
        // app, so the copy the player brought is never asked for a program of its own.
        progress("Preparing the program…", nil)
        guard let kit = Paths.programKit else {
            throw ImportFailure(message: "The program files are missing from this copy of the app, so the game cannot be prepared. This copy of the app is incomplete.")
        }
        for file in program {
            let src = kit.appendingPathComponent(file.dest.split(separator: "/").last.map(String.init) ?? file.dest)
            let dst = file.dest.split(separator: "/").reduce(gameStage) { $0.appendingPathComponent(String($1)) }
            let made = try copyHashed(src, dst)
            total += Int64(made.size)
            if made.size != file.size || made.sha256 != file.sha256 {
                throw ImportFailure(message: "The program files in this copy of the app are not the ones it was built with. This copy of the app is incomplete.")
            }
        }

        progress("Putting the game in place…", 1)
        removeTree(dest.appendingPathComponent("Disc"))
        try fm.moveItem(at: discStage, to: dest.appendingPathComponent("Disc"))
        removeTree(dest.appendingPathComponent("Game"))
        try fm.moveItem(at: gameStage, to: dest.appendingPathComponent("Game"))
        let volume = "label=\(label)\nfs=CDFS\nserial=\(String(format: "%08X", serial))\nsectors=\(sectors)\nimage_size=\(imageSize)\nimage_sha256=\(imageHash)\n"
        try volume.write(to: dest.appendingPathComponent("Disc.volume"), atomically: true, encoding: .utf8)
        try "image_sha256=\(imageHash)\nlabel=\(label)\nfiles=\(manifest.count)\nbytes=\(total)\n"
            .write(to: dest.appendingPathComponent("Game.imported"), atomically: true, encoding: .utf8)
        makeReadOnly(dest.appendingPathComponent("Disc"))
        updateSettings(game: dest.appendingPathComponent("Game"), disc: dest.appendingPathComponent("Disc"))
        progress("The game is set up from your disc.", 1)
    }

    private func makeReadOnly(_ root: URL) {
        guard let walker = fm.enumerator(at: root, includingPropertiesForKeys: nil) else { return }
        for case let url as URL in walker {
            var isDir: ObjCBool = false
            fm.fileExists(atPath: url.path, isDirectory: &isDir)
            try? fm.setAttributes([.posixPermissions: isDir.boolValue ? 0o555 : 0o444], ofItemAtPath: url.path)
        }
        try? fm.setAttributes([.posixPermissions: 0o555], ofItemAtPath: root.path)
    }

    private func updateSettings(game: URL, disc: URL) {
        let file = Paths.support.appendingPathComponent("settings.conf")
        var lines = (try? String(contentsOf: file, encoding: .utf8))?
            .split(omittingEmptySubsequences: false, whereSeparator: { $0.isNewline }).map(String.init) ?? []
        var wroteGame = false
        var wroteDisc = false
        for index in lines.indices {
            let trimmed = lines[index].trimmingCharacters(in: .whitespaces)
            if trimmed.hasPrefix("GAME_DIR=") { lines[index] = "GAME_DIR=\(game.path)"; wroteGame = true }
            if trimmed.hasPrefix("DISC_DIR=") { lines[index] = "DISC_DIR=\(disc.path)"; wroteDisc = true }
        }
        if !wroteGame { lines.append("GAME_DIR=\(game.path)") }
        if !wroteDisc { lines.append("DISC_DIR=\(disc.path)") }
        if lines.first?.hasPrefix("#") != true {
            lines.insert("# Black & White settings (written when your disc was added).", at: 0)
        }
        try? lines.joined(separator: "\n").write(to: file, atomically: true, encoding: .utf8)
    }
}

// MARK: - Handing over to the launcher

func execLauncher() -> Never {
    let launcher = Paths.launcher
    guard FileManager.default.isExecutableFile(atPath: launcher.path) else {
        FileHandle.standardError.write(Data("Black & White: the launcher is missing at \(launcher.path); this copy of the app is incomplete.\n".utf8))
        exit(1)
    }
    let bash = strdup("/bin/bash")
    let script = strdup(launcher.path)
    var argv: [UnsafeMutablePointer<CChar>?] = [bash, script, nil]
    execv("/bin/bash", &argv)
    FileHandle.standardError.write(Data("Black & White: the launcher could not be started.\n".utf8))
    exit(1)
}

// MARK: - Without a window

enum CommandLine_ {
    static func run(_ args: [String]) -> Int32? {
        guard let first = args.first else { return nil }
        switch first {
        case "--selftest":
            return SelfTest.run()
        case "--help":
            print("usage: BlackWhite [--selftest | --check-setup | --import-iso <image> | --import-disc <folder> | --import-folder <game folder>]")
            return 0
        case "--check-setup":
            let setup = currentSetup()
            print("game folder: \(setup.gameDir.path)")
            print("disc copy:   \(setup.discDir.path)")
            print("program:     \(setup.exe?.path ?? "none that matches this build")")
            if setup.complete {
                print("set up: yes")
                return 0
            }
            print("set up: no")
            for problem in setup.problems { print("  - \(problem)") }
            return 1
        case "--import-iso", "--import-disc", "--import-folder":
            guard args.count == 2 else { FileHandle.standardError.write(Data("one disc image or folder, please\n".utf8)); return 2 }
            let importer = Importer()
            importer.progress = { text, _ in print(text) }
            do {
                if first == "--import-iso" {
                    try importer.importISO(URL(fileURLWithPath: args[1]), into: Paths.support)
                } else if first == "--import-disc" {
                    try importer.importDiscFolder(URL(fileURLWithPath: args[1], isDirectory: true), into: Paths.support)
                } else {
                    try importer.importGameFolder(URL(fileURLWithPath: args[1], isDirectory: true), into: Paths.support)
                }
                let setup = currentSetup()
                guard setup.complete else {
                    FileHandle.standardError.write(Data("the import finished but set-up does not check out: \(setup.problems.joined(separator: "; "))\n".utf8))
                    return 1
                }
                print("game folder: \(setup.gameDir.path)")
                return 0
            } catch let failure as ImportFailure {
                FileHandle.standardError.write(Data((failure.message + "\n").utf8))
                return 1
            } catch {
                FileHandle.standardError.write(Data(("the import failed: \(error.localizedDescription)\n").utf8))
                return 1
            }
        default:
            return nil
        }
    }
}

// MARK: - Self-test

enum SelfTest {
    static var failures = 0

    static func check(_ ok: Bool, _ what: String) {
        print((ok ? "ok    " : "FAIL  ") + what)
        if !ok { failures += 1 }
    }

    static func run() -> Int32 {
        check(crc32(Data("123456789".utf8)) == 0xCBF4_3926, "crc32 of 123456789")
        let fm = FileManager.default
        let temp = fm.temporaryDirectory.appendingPathComponent("bw-frontdoor-\(UUID().uuidString)", isDirectory: true)
        defer { removeTree(temp) }
        do {
            try fm.createDirectory(at: temp, withIntermediateDirectories: true)
            let sample = temp.appendingPathComponent("sample")
            try Data("abc".utf8).write(to: sample)
            check(try sha256File(sample) == "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
                  "sha256 of a small file")

            let conf = temp.appendingPathComponent("settings.conf")
            try "# a note\nGAME_DIR=/first\nGAME_DIR=\"/second\"\nSCREEN_MODE=window\n".write(to: conf, atomically: true, encoding: .utf8)
            let values = readConf(conf)
            check(values["GAME_DIR"] == "/second" && values["SCREEN_MODE"] == "window",
                  "a settings file reads, the last value counting, quotes dropped")

            let (manifest, program) = try loadManifest()
            check(manifest.count == 1063, "the manifest lists 1063 content files (found \(manifest.count))")
            check(program.count == 5 && program.contains { $0.dest == "runblack.exe" && $0.sha256 == fallbackPin },
                  "the manifest's program is the one this build was made from")

            let empty = evaluate(gameDir: temp.appendingPathComponent("Game"),
                                 discDir: temp.appendingPathComponent("Disc"),
                                 exeNamed: nil, pin: fallbackPin)
            check(!empty.complete && !empty.problems.isEmpty, "an empty folder is not set up")

            let game = temp.appendingPathComponent("Game")
            let disc = temp.appendingPathComponent("Disc")
            for needed in ["lhlogr.dll", "LHaudiodllR.dll", "LHMultiplayerR.dll", "Plug Ins/ScriptLibraryR.dll"] {
                let file = game.appendingPathComponent(needed)
                try fm.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
                fm.createFile(atPath: file.path, contents: Data())
            }
            try fm.createDirectory(at: disc, withIntermediateDirectories: true)
            try "label=BNW\n".write(to: URL(fileURLWithPath: disc.path + ".volume"), atomically: true, encoding: .utf8)
            let exe = game.appendingPathComponent("runblack.exe")
            try Data(" stand-in".utf8).write(to: exe)
            let ready = evaluate(gameDir: game, discDir: disc, exeNamed: nil, pin: try sha256File(exe))
            check(ready.complete && ready.exe == exe, "a folder with the right files and program is set up")

            let sectorFile = temp.appendingPathComponent("fake.iso")
            var sector = Data(count: 2048)
            sector[0] = 1
            sector.replaceSubrange(1..<6, with: Data("CD001".utf8))
            sector.replaceSubrange(40..<44, with: Data("BNW ".utf8))
            sector[80] = 100
            try sector.write(to: sectorFile)
            let handle = try FileHandle(forWritingTo: sectorFile)
            try handle.truncate(atOffset: 16 * 2048)
            try handle.seek(toOffset: 16 * 2048)
            try handle.write(contentsOf: sector)
            try handle.close()
            let descriptor = try readVolumeDescriptor(sectorFile)
            check(descriptor.label == "BNW" && descriptor.sectors == 100, "a disc image's volume descriptor reads")
        } catch {
            check(false, "self-test setup: \(error.localizedDescription)")
        }
        print(failures == 0 ? "all checks passed" : "\(failures) checks failed")
        return failures == 0 ? 0 : 1
    }
}

// MARK: - The set-up window

@MainActor
final class SetupModel: ObservableObject {
    @Published var status = "This Mac port of Black & White comes with no game files. Add your own copy of the game — its disc, or the folder it is installed in — and it sets itself up from it; after that it starts at once."
    @Published var busy = false
    @Published var ready = false
    @Published var fraction: Double?

    func chooseImage() {
        let panel = NSOpenPanel()
        panel.title = "Choose your Black & White disc image"
        panel.message = "The .iso image of your Black & White disc. It is only read."
        panel.canChooseDirectories = false
        panel.canChooseFiles = true
        panel.allowsMultipleSelection = false
        panel.allowsOtherFileTypes = true
        panel.allowedContentTypes = [UTType(filenameExtension: "iso"), UTType(filenameExtension: "img")].compactMap { $0 }
        if panel.runModal() == .OK, let url = panel.url { start { try Importer().importISO(url, into: Paths.support) } }
    }

    func chooseFolder() {
        let panel = NSOpenPanel()
        panel.title = "Choose a copy of your Black & White disc"
        panel.message = "The folder that holds the disc's files (data1.cab at the top). It is only read."
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.allowsMultipleSelection = false
        if panel.runModal() == .OK, let url = panel.url { start { try Importer().importDiscFolder(url, into: Paths.support) } }
    }

    func chooseGameFolder() {
        let panel = NSOpenPanel()
        panel.title = "Choose your installed Black & White folder"
        panel.message = "The folder the game is installed in (it holds the Data and Scripts folders). It is only read."
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.allowsMultipleSelection = false
        if panel.runModal() == .OK, let url = panel.url { start { try Importer().importGameFolder(url, into: Paths.support) } }
    }

    private func start(_ work: @escaping () throws -> Void) {
        busy = true
        ready = false
        let model = self
        DispatchQueue.global(qos: .userInitiated).async {
            let importer = Importer()
            importer.progress = { text, fraction in
                DispatchQueue.main.async {
                    model.status = text
                    model.fraction = fraction
                }
            }
            do {
                try work()
                DispatchQueue.main.async {
                    model.busy = false
                    model.ready = currentSetup().complete
                    model.status = model.ready
                        ? "Set up from your disc. Play whenever you are ready; the disc is not needed again until you set up afresh."
                        : "The import finished, but set-up does not check out. Try adding the disc again."
                }
            } catch let failure as ImportFailure {
                DispatchQueue.main.async {
                    model.busy = false
                    model.status = failure.message
                }
            } catch {
                DispatchQueue.main.async {
                    model.busy = false
                    model.status = "Set-up failed: \(error.localizedDescription)"
                }
            }
        }
    }

    func play() { execLauncher() }
}

struct SetupView: View {
    @StateObject private var model = SetupModel()

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("Black & White").font(.largeTitle).bold()
            Text("For Mac").font(.title3).foregroundStyle(.secondary)
            Text(model.status).fixedSize(horizontal: false, vertical: true)
            if model.busy {
                if let fraction = model.fraction {
                    ProgressView(value: fraction)
                } else {
                    ProgressView()
                }
            }
            HStack(spacing: 12) {
                Button("Choose Disc Image…") { model.chooseImage() }
                    .disabled(model.busy)
                Button("Choose Disc Folder…") { model.chooseFolder() }
                    .disabled(model.busy)
                Button("Choose Installed Game…") { model.chooseGameFolder() }
                    .disabled(model.busy)
                Spacer()
                if model.ready {
                    Button("Play Black & White") { model.play() }
                        .keyboardShortcut(.defaultAction)
                }
            }
            Text("Any complete copy of the game works: the original disc, a patched copy, or another language edition. What you choose is only read, and is not needed again after set-up. About 3 GB of disk space is used. Set-up takes under a minute on most Macs.")
                .font(.caption).foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(24)
        .frame(width: 560)
    }
}

final class FrontDoorDelegate: NSObject, NSApplicationDelegate {
    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { true }
}

struct FrontDoorApp: App {
    @NSApplicationDelegateAdaptor(FrontDoorDelegate.self) private var delegate

    var body: some Scene {
        WindowGroup("Black & White — Add Your Disc") {
            SetupView()
        }
        .windowResizability(.contentSize)
    }
}

// MARK: - Start

@main
struct Entry {
    static func main() {
        let args = Array(CommandLine.arguments.dropFirst())
        if let code = CommandLine_.run(args) { exit(code) }
        // The test switches keep their old meaning: the launcher answers them directly.
        if envValue("BW_APP_DRYRUN") != nil || envValue("BW_APP_PRINT_SETTINGS") != nil { execLauncher() }
        if currentSetup().complete { execLauncher() }
        FrontDoorApp.main()
    }
}
